دسترسی تجهیزات 83% شده. چه اتفاقی افتاده؟ (مدیر تعمیرات — معدن سنگ‌آهن چادرملو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "equipment_downtime",
      "description": "توقف تجهیزات به تفکیک نوع و علت",
      "dimensions": [
        "equipment",
        "reason",
        "period"
      ],
      "measures": [
        "hours",
        "cost"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "availability",
      "description": "نرخ دسترسی تجهیز",
      "formula": "زمان کار / (زمان کار + زمان توقف)",
      "unit": "درصد",
      "dimensions": [
        "equipment"
      ]
    }
  ],
  "business_context": [
    "ناوگان تجهیزات معدنی شامل شاول، دامپر، سنگ‌شکن و آسیاب",
    "تعمیرات پیشگیرانه و اضطراری با بودجهٔ سالانه",
    "قطعات حیاتی با زمان تحویل طولانی (۳ تا ۶ ماه)"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "availability"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ]
  }
}

TOOL_OBSERVATION:
{
  "availability": {
    "prev": 94,
    "curr": 83
  }
}

